import {t} from './i18n.mjs';

function signalCopy(signal) {
  const count = signal.cardIds?.length ?? 0;
  const copy = {
    'shared-phone': [
      t('Shared phone number', signal.title, '전화번호 중복'),
      t('Multiple accounts use this phone number. Check whether it is a shared number before taking action.', signal.explanation, '여러 계정에서 같은 전화번호를 사용합니다. 조치하기 전에 공동으로 사용하는 번호인지 확인하세요.'),
    ],
    'matching-profile': [
      t('Matching name and age', signal.title, '이름과 나이 일치'),
      t('Review the profiles to determine whether they belong to the same person.', signal.explanation, '프로필을 검토하여 동일인인지 확인하세요.'),
    ],
    'duplicate-story': [
      t('Matching stories across accounts', signal.title, '서로 다른 계정에서 동일한 사연'),
      t('The stories match after text normalisation. Review the submissions and verify their context.', signal.explanation, '텍스트를 정규화한 결과 사연이 일치합니다. 제출된 내용과 맥락을 확인하세요.'),
    ],
    'submission-burst': [
      t('Multiple cards in 24 hours', signal.title, '24시간 내 다수 카드 제출'),
      t(`This account submitted ${count} cards in the last 24 hours. Review the submissions for context.`, signal.explanation, `이 계정은 지난 24시간 동안 카드 ${count}장을 제출했습니다. 제출 내용을 검토하세요.`),
    ],
  };
  return Object.hasOwn(copy, signal.type) ? copy[signal.type] : [signal.title, signal.explanation];
}
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function initFraudMonitoring({root,call,back}){
 let signals=[],users=[],selected=null,query='',blockedOnly=false,busy=false,checkedAt='';
 function message(text){const field=document.querySelector('#safety-feedback');if(field)field.textContent=text;}
 async function search(){const result=await call('admin/users?q='+encodeURIComponent(query)+(blockedOnly?'&blocked=1':''));users=result.users;renderUsers();}
 async function show(){root.innerHTML=`<p>${t("Loading fraud monitoring…","Đang tải Fraud Monitoring…","이상 활동 모니터링을 불러오는 중…")}</p>`;try{const result=await call('admin/fraud');signals=result.signals;checkedAt=result.checkedAt;selected=null;query='';blockedOnly=false;render();await search();}catch(error){root.innerHTML=`<h1>${t("Fraud monitoring","Fraud Monitoring","이상 활동 모니터링")}</h1><p id="safety-feedback" role="alert"></p><button id="safety-back">${t("← Review cards","← Duyệt thẻ","← 카드 검토")}</button>`;message(error.message);document.querySelector('#safety-back').onclick=back;}}
 function render(){root.innerHTML=`<section class="management-heading"><div><span class="eyebrow">${t("COMMUNITY SAFETY","COMMUNITY SAFETY","커뮤니티 안전")}</span><h1>${t("Fraud monitoring","Fraud Monitoring","이상 활동 모니터링")}</h1><p>${t("Review activity flagged by the system. Admins decide whether to block accounts.","Phát hiện dấu hiệu cần xem xét. Mọi quyết định chặn do admin thực hiện.","시스템에서 감지한 활동을 검토하세요. 계정 차단 여부는 관리자가 결정합니다.")}</p></div><button class="secondary" id="safety-back">${t("← Review cards","← Duyệt thẻ","← 카드 검토")}</button></section><div class="safety-overview"><div><strong>${signals.length}</strong><span>${t("Alerts to review","Cảnh báo cần kiểm tra","검토할 알림")}</span></div><div><strong>${t("24 hours","24 giờ","24시간")}</strong><span>${t("Window for monitoring submission bursts","Khoảng theo dõi gửi thẻ dồn dập","집중 제출 감지 기간")}</span></div><div><strong>${t("Documents","Giấy tờ","증빙 서류")}</strong><span>${t("No data · Document uploads unavailable","Chưa có dữ liệu · Chưa hỗ trợ tải giấy tờ","데이터 없음 · 증빙 서류 업로드 미지원")}</span></div></div><section class="safety-signals"><div class="safety-section-heading"><h2>${t("Automatic alerts","Cảnh báo tự động","자동 감지 알림")}</h2><small>${t("Updated: ","Cập nhật: ","업데이트: ")}${e(new Date(checkedAt).toLocaleString(t('en-AU','vi-VN','ko-KR')))}</small></div><p class="safety-explainer">${t("People can legitimately share a name, age or phone number. Alerts prompt manual review of profiles and card submissions. Document checks, creditor verification and payment monitoring are unavailable.","Trùng tên, tuổi hoặc số điện thoại có thể hợp lệ. Các dấu hiệu này không phải bằng chứng gian lận; không tự động chặn tài khoản. Hiện chỉ đối chiếu dữ liệu hồ sơ và thẻ đã gửi, chưa kiểm tra giấy tờ, chủ nợ hoặc hành vi thanh toán.","이름, 나이 또는 전화번호가 같은 데에는 정상적인 이유가 있을 수 있습니다. 알림이 표시되면 프로필과 제출 카드를 직접 검토하세요. 증빙 서류, 채권자 및 결제 활동은 확인할 수 없습니다.")}</p><div class="safety-signal-grid">${signals.length?signals.map(s=>{const [title,explanation]=signalCopy(s);return `<article class="safety-signal"><span class="status-badge">${t("Needs review","Cần xem xét","검토 필요")}</span><h3>${e(title)}</h3><p>${e(explanation)}</p><div>${s.members.map(member=>`<button class="secondary" data-signal-member="${e(member.id)}">${e(member.name)}${member.blocked?t(" · Blocked"," · Đã chặn"," · 차단됨"):''} ↗</button>`).join('')}</div></article>`;}).join(''):`<p class="safety-empty">${t("Current rules found no duplicate patterns or bursts of card submissions.","Chưa phát hiện dấu hiệu trùng lặp hoặc gửi thẻ dồn dập theo các quy tắc hiện tại.","현재 기준으로 정보 중복이나 짧은 시간 내 다수의 카드 제출이 발견되지 않았습니다.")}</p>`}</div></section><section class="safety-members"><h2>${t("Manage members","Quản lý thành viên","회원 관리")}</h2><form id="safety-search"><label for="safety-query">${t("Search by name, nickname or email","Tìm tên thành viên, biệt danh hoặc email","이름, 닉네임 또는 이메일로 검색")}</label><div><input id="safety-query" name="query" type="search" maxlength="100" placeholder="${t("Enter a member’s name…","Nhập tên thành viên…","회원 이름 입력…")}"><button>${t("Search","Tìm kiếm","검색")}</button></div></form><label class="safety-block-filter"><input id="safety-blocked" type="checkbox">${t(" Show blocked accounts only"," Chỉ hiện tài khoản đã chặn"," 차단된 계정만 보기")}</label><div class="safety-workspace"><div id="safety-user-list"></div><div id="safety-action-panel"><div class="review-placeholder"><h3>${t("Select a member","Chọn thành viên","회원 선택")}</h3><p>${t("View activity, send a notice or block an account.","Xem lịch sử, gửi thông báo hoặc chặn tài khoản.","조치 내역을 확인하거나 알림을 보내거나 계정을 차단할 수 있습니다.")}</p></div></div></div></section><p id="safety-feedback" role="alert"></p>`;
 document.querySelector('#safety-back').onclick=()=>{if(!busy)back();};
 document.querySelector('#safety-search').onsubmit=async event=>{event.preventDefault();if(busy)return;query=document.querySelector('#safety-query').value.trim();selected=null;try{await search();document.querySelector('#safety-action-panel').innerHTML='';message('');}catch(error){message(error.message);}};
 document.querySelector('#safety-blocked').onchange=async event=>{if(busy){event.target.checked=blockedOnly;return;}blockedOnly=event.target.checked;try{await search();}catch(error){message(error.message);}};
 root.querySelectorAll('[data-signal-member]').forEach(button=>button.onclick=async()=>{if(busy)return;query=button.dataset.signalMember;document.querySelector('#safety-query').value=query;try{await search();await select(users.find(user=>user.id===query));document.querySelector('#safety-members-title')?.focus();}catch(error){message(error.message);}});
 }
 function renderUsers(){const shown=users.filter(user=>!blockedOnly||user.blocked);document.querySelector('#safety-user-list').innerHTML=shown.length?shown.map(user=>`<button class="safety-user ${selected?.id===user.id?'selected':''}" data-safety-user="${e(user.id)}"><strong>${e(user.name)}</strong><small>${e(user.email||user.nickname)}</small><span class="status-badge ${user.blocked?'rejected':'approved'}">${user.blocked?t("Blocked","Đã chặn","차단됨"):t("Active","Hoạt động","활성")}</span>${user.protected?`<small>${t("Admin account · Protected","Tài khoản admin · được bảo vệ","관리자 계정 · 보호됨")}</small>`:''}</button>`).join(''):`<p class="safety-empty">${t("No matching members. Each search returns up to 100 results.","Không có thành viên phù hợp. Tối đa 100 kết quả mỗi lần tìm kiếm.","일치하는 회원이 없습니다. 검색당 최대 100개의 결과를 표시합니다.")}</p>`;root.querySelectorAll('[data-safety-user]').forEach(button=>button.onclick=()=>{if(!busy)select(users.find(user=>user.id===button.dataset.safetyUser));});}
 async function select(user){if(!user)return;selected=user;renderUsers();const panel=document.querySelector('#safety-action-panel');panel.innerHTML=`<div class="safety-selected"><h3 id="safety-members-title" tabindex="-1">${e(user.name)}</h3><p>${e(user.email||user.nickname)}</p><small>ID: ${e(user.id)}</small><p>${user.blocked?`${t("Blocked · ","Đã chặn · ","차단됨 · ")}${e(user.blockReason)}`:t("This account is active.","Tài khoản đang hoạt động.","활성 상태인 계정입니다.")}</p><form id="safety-actions"><label for="safety-message">${t("Notice or reason for action","Nội dung thông báo / lý do xử lý","알림 내용 또는 조치 사유")}</label><textarea id="safety-message" maxlength="1000" required placeholder="${t("Enter a notice or a reason for blocking or unblocking…","Nhập thông báo cho thành viên hoặc lý do chặn / mở chặn…","알림 내용 또는 차단이나 차단 해제 사유 입력…")}"></textarea><p class="member-help">${t("Members receive notices in the app. Blocking an account signs the member out and hides their cards from Discover. The member will see the reason when they try to sign in.","Thông báo được lưu trong app, không gửi email hoặc SMS. Tài khoản bị chặn sẽ bị ngắt phiên đăng nhập và thẻ được ẩn khỏi trang quẹt. Thành viên sẽ thấy lý do khi thử đăng nhập.","회원은 앱에서 알림을 받습니다. 계정을 차단하면 회원이 로그아웃되고 둘러보기에서 해당 카드가 숨겨집니다. 회원이 다시 로그인할 때 차단 사유가 표시됩니다.")}</p><div class="review-actions"><button type="submit" name="action" value="notify" class="secondary">${t("Send notice","Gửi thông báo","알림 보내기")}</button><button type="submit" name="action" value="block" ${user.protected&&!user.blocked?'disabled':''}>${user.blocked?t("Unblock","Mở chặn","차단 해제"):t("Block user","Chặn người dùng","사용자 차단")}</button></div></form><h4>${t("Action history","Lịch sử xử lý","조치 내역")}</h4><div id="safety-history">${t("Loading…","Đang tải…","불러오는 중…")}</div></div>`;
 document.querySelector('#safety-actions').onsubmit=async event=>{event.preventDefault();if(busy)return;const action=event.submitter?.value,text=document.querySelector('#safety-message').value.trim();if(!text){message(t("Enter a notice or a reason for this action.","Vui lòng nhập nội dung hoặc lý do xử lý.","알림 내용 또는 조치 사유를 입력하세요."));return;}if(!['notify','block'].includes(action))return;busy=true;const buttons=[...event.target.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await call('admin/users/'+encodeURIComponent(user.id)+'/'+action,action==='notify'?{message:text}:{blocked:!user.blocked,reason:text});await search();const updated=users.find(u=>u.id===user.id);if(updated)await select(updated);else{selected=null;document.querySelector('#safety-action-panel').innerHTML='';}message(action==='notify'?t(`Sent an in-app notice to ${user.name}.`,`Đã gửi thông báo trong app cho ${user.name}.`,`${user.name} 회원에게 앱 알림을 보냈습니다.`):user.blocked?t("Account unblocked. The member must sign in again.","Đã mở chặn. Thành viên cần đăng nhập lại.","차단을 해제했습니다. 회원이 다시 로그인해야 합니다."):t("Account blocked and cards hidden from Discover.","Đã chặn tài khoản và ẩn thẻ khỏi trang quẹt.","계정을 차단하고 둘러보기에서 카드를 숨겼습니다."));}catch(error){message(error.message);buttons.forEach(b=>b.disabled=false);}finally{busy=false;}};
 try{const {events}=await call('admin/users/'+encodeURIComponent(user.id)+'/history');if(selected?.id!==user.id)return;document.querySelector('#safety-history').innerHTML=events.length?events.map(event=>`<article class="safety-history-item"><strong>${({notify:t("Send notice","Gửi thông báo","알림 보내기"),block:t("Block account","Chặn tài khoản","계정 차단"),unblock:t("Unblock","Mở chặn","차단 해제")})[event.action]||e(event.action)}</strong><small>${e(new Date(event.createdAt).toLocaleString(t('en-AU','vi-VN','ko-KR')))}</small><p>${e(event.reason)}</p></article>`).join(''):`<p>${t("No action history yet.","Chưa có lịch sử xử lý.","조치 내역이 없습니다.")}</p>`;}catch(error){if(selected?.id===user.id)document.querySelector('#safety-history').textContent=error.message;}
 }
 return {show};
}
